import{_ as e,o as a,c as o,k as r}from"./chunks/framework.ystBm8og.js";const u=JSON.parse('{"title":"Privacy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy.md","filePath":"guide/privacy.md","lastUpdated":1785751237000}'),i={name:"guide/privacy.md"};function d(s,t,n,l,c,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h1><p>Pomodoro is <strong>local-first</strong>. There is no account, no cloud sync, and no telemetry built into the app.</p><h2 id="what-is-stored" tabindex="-1">What is stored <a class="header-anchor" href="#what-is-stored" aria-label="Permalink to &quot;What is stored&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Where</th><th>Purpose</th></tr></thead><tbody><tr><td>Settings</td><td>App data dir, JSON store</td><td>Durations, toggles, accent</td></tr><tr><td>Tasks / todos</td><td>App data dir, JSON store</td><td>Titles, completion, pomodoro counts, active task</td></tr><tr><td>Session history</td><td>App data dir, SQLite (<code>pomodoro.db</code>)</td><td>Phase outcomes for stats and the Sessions sheet</td></tr></tbody></table><p>Exact paths depend on the OS (Tauri app data directory for the bundle identifier <code>com.pomodoro.app</code>).</p><h2 id="what-is-not-collected" tabindex="-1">What is not collected <a class="header-anchor" href="#what-is-not-collected" aria-label="Permalink to &quot;What is not collected&quot;">​</a></h2><ul><li>No sign-in</li><li>No analytics or crash reporting service</li><li>No network requirement for core timer features</li><li>No automatic upload of tasks or history</li></ul><p>Notifications and tray use the operating system APIs on your machine only.</p><h2 id="uninstall-wipe" tabindex="-1">Uninstall / wipe <a class="header-anchor" href="#uninstall-wipe" aria-label="Permalink to &quot;Uninstall / wipe&quot;">​</a></h2><p>Removing the app does not always delete app data. To wipe local state, delete the application data folder for Pomodoro after quitting the app (location varies by OS).</p><h2 id="open-source" tabindex="-1">Open source <a class="header-anchor" href="#open-source" aria-label="Permalink to &quot;Open source&quot;">​</a></h2><p>You can audit storage and behavior in the source:</p><ul><li><a href="https://github.com/nikhilakki/pomodoro" target="_blank" rel="noreferrer">nikhilakki/pomodoro</a></li></ul>',13)])])}const m=e(i,[["render",d]]);export{u as __pageData,m as default};
